#: Courses already submitted and not yet past payment: their prices are
#: locked by this migration so the new payout rules can pay them.
IN_FLIGHT = ("SUBMITTED", "IN_REVIEW", "AWAITING_VIDEO", "NEEDS_REVISION", "QA_VERIFICATION", "APPROVED")
TYPES = ("WITHOUT_VIDEO", "WITH_VIDEO", "AI_BUILT")


def backfill_payouts(apps, schema_editor):
    """Bring existing courses onto the new payout fields.

    * A course whose creator's wallet was already credited for it is marked
      paid (`creator_paid_at`), so it is never paid twice.
    * An unpaid course in review keeps the amount it was promised: all three
      locked rates are its old snapshot. An AI-generated one, which was never
      priced, is locked at its topic's (or category's) AI-built price now.
    * Its payout type follows its source and who makes its video.
    """

    Course = apps.get_model("courses", "Course")
    Transaction = apps.get_model("payments", "Transaction")
    ContentType = apps.get_model("contenttypes", "ContentType")

    wallet_type = ContentType.objects.filter(app_label="wallet", model="wallet").first()
    paid = {}
    if wallet_type is not None:
        for course_id, created in (
            Transaction.objects.filter(type="CREDIT", wallet_type=wallet_type, course_id__isnull=False)
            .order_by("created_datetime")
            .values_list("course_id", "created_datetime")
        ):
            paid.setdefault(course_id, created)

    courses = list(
        Course.objects.filter(submitted_at__isnull=False).select_related("topic", "category")
    )
    for course in courses:
        course.creator_paid_at = paid.get(course.id)
        if course.source_type == "AI_GENERATED":
            course.payout_type = "AI_BUILT"
        elif course.video_provider == "PRODUCTION_ENGINE":
            course.payout_type = "WITHOUT_VIDEO"
        else:
            course.payout_type = "WITH_VIDEO"
        if course.creator_paid_at is None and course.status in IN_FLIGHT:
            if course.creator_price_snapshot is not None:
                course.creator_rates_snapshot = {kind: str(course.creator_price_snapshot) for kind in TYPES}
            elif course.payout_type == "AI_BUILT":
                topic_price = course.topic.creator_price_ai_built if course.topic_id else None
                price = topic_price if topic_price is not None else course.category.creator_price_ai_built
                course.creator_rates_snapshot = {"AI_BUILT": str(price)}
                course.creator_price_snapshot = price
    Course.objects.bulk_update(
        courses,
        ["creator_paid_at", "payout_type", "creator_rates_snapshot", "creator_price_snapshot"],
        batch_size=500,
    )


